// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address[] memory accounts, uint256[] memory ids) public {
        // Ensure arrays have different lengths for meaningful test
        vm.assume(accounts.length != ids.length);

        // Record whether balanceOfBatch reverts
        bool reverted = false;
        try c.balanceOfBatch(accounts, ids) {
            // No revert means bug is present or reference would also fail; but reference must revert
        } catch {
            reverted = true;
        }

        // The reference should revert; the buggy version should not
        assertTrue(reverted, "balanceOfBatch should revert when lengths differ");
    }
}

